// IPC DTO types are generated by ts-rs from the Rust structs into
// src/bindings/ (regenerated by `cargo test`, committed, CI diff-guarded).
// This shim is the single import home for the skills world: components
// import from here, never from src/bindings/ directly.

export type { OnboardingVariant } from "../../bindings/OnboardingVariant";
export type { OnboardingGroup } from "../../bindings/OnboardingGroup";
export type { OnboardingPlan } from "../../bindings/OnboardingPlan";
// Aliased: the frontend has always called this ManagedSkill; the Rust
// struct (and generated binding) is ManagedSkillDto.
export type { ManagedSkillDto as ManagedSkill } from "../../bindings/ManagedSkillDto";
export type { SkillTargetDto } from "../../bindings/SkillTargetDto";
export type { SyncStatus } from "../../bindings/SyncStatus";
export type { SyncMode } from "../../bindings/SyncMode";
export type { GitSkillCandidate } from "../../bindings/GitSkillCandidate";
export type { LocalSkillCandidate } from "../../bindings/LocalSkillCandidate";
export type { InstallResultDto } from "../../bindings/InstallResultDto";
export type { UpdateResultDto } from "../../bindings/UpdateResultDto";
export type { AppSettings } from "../../bindings/AppSettings";
export type { SettingUpdate } from "../../bindings/SettingUpdate";
export type { SettingsBounds } from "../../bindings/SettingsBounds";
export type { FeaturedSkillDto } from "../../bindings/FeaturedSkillDto";
export type { OnlineSkillDto } from "../../bindings/OnlineSkillDto";
export type { SkillFileEntry } from "../../bindings/SkillFileEntry";
export type { ToolInfoDto } from "../../bindings/ToolInfoDto";
export type { ToolStatusDto } from "../../bindings/ToolStatusDto";
export type { BatchSyncSkillDto } from "../../bindings/BatchSyncSkillDto";
export type { BatchSyncOverrideDto } from "../../bindings/BatchSyncOverrideDto";
export type { BatchSyncPolicyDto } from "../../bindings/BatchSyncPolicyDto";
export type { BatchSyncReportDto } from "../../bindings/BatchSyncReportDto";
export type { SyncTargetResultDto } from "../../bindings/SyncTargetResultDto";
export type { SyncTargetStatusDto } from "../../bindings/SyncTargetStatusDto";
export type { SyncProgressDto } from "../../bindings/SyncProgressDto";

